function payload(){const t=calcTotals(),snap=JSON.parse(JSON.stringify(settings));snap.invoiceTax=taxConfig(settings);delete snap.supabaseKey;delete snap.supabaseUrl;delete snap.products;if(snap.logoData&&String(snap.logoData).length>150000)snap.logoData='';return{id:currentId,source_quote_id:sourceQuoteId,customer_id:selectedCustomerId,invoice_number:$('invoiceNumber').value,invoice_date:$('invoiceDate').value,due_date:$('dueDate').value,customer_name:$('customerName').value.trim(),customer_address:$('customerAddress').value.trim(),customer_email:$('customerEmail').value.trim(),customer_contact_name:$('invoiceBillingContact')?.value.trim()||'',customer_phone:$('invoiceCustomerPhone')?.value.trim()||'',customer_mobile:$('invoiceCustomerMobile')?.value.trim()||'',customer_category:$('invoiceCustomerCategory')?.value.trim()||'',reference:$('reference').value.trim(),customer_note:$('customerNote').value.trim(),items:items.map(x=>({...x})),subtotal:t.subtotal,discount_type:t.discountType,discount_value:t.discountValue,discount_amount:t.discountAmount,extra_fee:t.extraFee,gst:t.gst,total:t.total,amount_paid:t.amountPaid,balance_due:t.balanceDue,recurring:$('recurringEnabled').checked,recurring_frequency:$('recurringEnabled').checked?$('recurringFrequency').value:null,company_snapshot:snap,updated_at:new Date().toISOString()}}
