async function persistInvoice(p,isEdit=false){
  // v22: cloud is the source of truth for signed-in SaaS accounts.
  // Local storage remains a cache/fallback and is clearly marked when sync is pending.
  const saasMode=!!window.SAAS;
  if(!sb){
    const local=cacheInvoice({...p,_sync_pending:saasMode},isEdit);
    if(saasMode)toast('Saved on this device only — cloud sync is pending.');
    return local;
  }
  try{
    const row={...p};delete row.id;delete row._sync_pending;
    const cloudEdit=isEdit&&p.id&&!String(p.id).startsWith('local-');
    const r=cloudEdit?await sb.from('invoices').update(row).eq('id',p.id).select().single():await sb.from('invoices').insert(row).select().single();
    if(!r.error&&r.data){const synced=cacheInvoice({...r.data,_sync_pending:false},isEdit);return synced||r.data}
    console.warn('Supabase invoice save failed:',r.error);
    const local=cacheInvoice({...p,_sync_pending:true},isEdit);
    toast('Invoice saved on this device, but cloud sync is pending: '+(r.error?.message||'Unknown error'));
    return local;
  }catch(err){
    console.warn('Supabase invoice save threw an error:',err);
    const local=cacheInvoice({...p,_sync_pending:true},isEdit);
    toast('Invoice saved on this device, but cloud sync is currently unavailable.');
    return local;
  }
}
async function save(){
  if(window.SAAS?.canCreateInvoice){const gate=await window.SAAS.canCreateInvoice();if(!gate.ok){toast(gate.message);window.SAAS.showPlans?.();return null}}
  if(!validate())return null;
  let p=payload();
  const wasEdit=!!currentId;
  // Customer lookup/creation must never block invoice saving.
  try{
    const customer=await ensureInvoiceCustomer(p);
    if(customer){selectedCustomerId=customer.id;p.customer_id=customer.id;p.customer_name=customer.name||p.customer_name;p.customer_address=customer.address||p.customer_address;const bc=billingContact(customer);if(bc){p.customer_email=bc.email||p.customer_email;p.customer_contact_name=bc.name||p.customer_contact_name;p.customer_phone=bc.phone||p.customer_phone;p.customer_mobile=bc.mobile||p.customer_mobile}else p.customer_email=customer.email||p.customer_email}
  }catch(err){console.warn('Customer sync skipped so invoice can still save:',err)}
  const r=await persistInvoice(p,wasEdit);
  if(!r)return null;
  currentId=r.id;
  try{await syncRecurringRule(r)}catch(err){console.warn('Recurring rule sync failed after invoice was saved:',err)}
  window.SAAS?.refreshUsage?.();
  return r
}
async function allInvoices(){
  const local=localInvoices();
  if(!sb)return local;
  try{
    const{data,error}=await sb.from('invoices').select('*').order('created_at',{ascending:false});
    if(error){console.warn('Supabase invoice read failed; showing local invoices:',error);return local}
    const merged=[],seen=new Set();
    // De-duplicate primarily by invoice number so a locally saved invoice and its cloud-synced copy do not show twice.
    for(const x of [...(data||[]),...local]){const k=String(x.invoice_number||x.id||'');if(!k||seen.has(k))continue;seen.add(k);merged.push(x)}
    return merged.map(x=>{const st=getEmailStatus(x);return st.sent?{...x,email_sent:true,last_sent_to:st.to,last_sent_at:st.at}:x}).sort((a,b)=>String(b.created_at||b.invoice_date||'').localeCompare(String(a.created_at||a.invoice_date||'')))
  }catch(err){console.warn('Supabase invoice read threw an error; showing local invoices:',err);return local}
}
