function previewHtml(inv){const snap=inv.company_snapshot||settings,bank=defaultBank(snap),t={...DEFAULT_SETTINGS.invoiceText,...(snap.invoiceText||{})},c=invoiceCalcFrom(inv);const discount=c.discountAmount>0?`<div><span>Discount</span><span>-${money(c.discountAmount)}</span></div>`:'',fee=c.extraFeeEnabled&&c.extraFeeRate!==0?`<div><span>${esc(c.extraFeeLabel)} (${c.extraFeeRate}%)</span><span>${money(c.extraFee)}</span></div>`:'',paid=c.amountPaid>0?`<div><span>Amount paid</span><span>${money(c.amountPaid)}</span></div><div class="balance"><span>Balance due</span><span>${money(c.balanceDue)}</span></div>`:'';return `<div class="inv-preview template-${esc(snap.template||settings.template)}"><div class="inv-preview-head">${logoSrc(snap)?`<img src="${esc(logoSrc(snap))}">`:''}<div class="inv-company"><strong>${esc(snap.company||settings.company)}</strong><br>${esc(snap.address||settings.address)}<br>${esc(snap.phone||settings.phone)} · ${esc(snap.email||settings.email)}${snap.website?'<br>'+esc(snap.website):''}<br>GST No: ${esc(snap.gstNumber||'Not set')}</div></div><div class="inv-title"><div><h2>${esc(t.invoiceTitle||'INVOICE')}</h2><div>${esc(inv.invoice_number)}</div></div><div><strong>${esc(t.billTo||'Bill To')}</strong><br>${esc(inv.customer_name)}${inv.customer_address?'<br>'+esc(inv.customer_address).replace(/\n/g,'<br>'):''}</div></div><p><strong>${esc(t.invoiceDate||'Invoice date')}:</strong> ${esc(inv.invoice_date)} &nbsp; <strong>${esc(t.dueDate||'Due date')}:</strong> ${esc(inv.due_date)}</p><table class="inv-table"><thead><tr><th>${esc(t.description||'Description')}</th><th>${esc(t.qty||'Qty')}</th><th>${esc(t.unitPrice||'Unit (ex GST)')}</th><th>${esc(t.lineTotal||'Amount')}</th></tr></thead><tbody>${(inv.items||[]).map(x=>`<tr><td>${esc(x.description)}${x.custom?' - '+esc(x.custom):''}</td><td>${num(x.qty)}</td><td>${money(x.unit_price)}</td><td>${money(num(x.qty)*num(x.unit_price))}</td></tr>`).join('')}</tbody></table><div class="inv-summary"><div><span>${esc(t.subtotal||'Subtotal (ex GST)')}</span><span>${money(c.subtotal)}</span></div>${discount}${fee}<div><span>${esc(cleanTaxLabel(t.gst,'GST'))} (${c.gstRate}%)</span><span>${money(c.gst)}</span></div><div class="grand"><span>${esc(t.total||'Total')}</span><span>${money(c.total)}</span></div>${paid}</div><div class="inv-footer"><strong>${esc(t.paymentTo||'Payment to')}:</strong> ${esc(bank.name?bank.name+' - ':'')}${esc(bank.account||'Bank account not set')}<br><strong>${esc(t.paymentReference||'Payment reference')}:</strong> ${esc(inv.invoice_number)}<br><span>${esc(t.paymentInstruction||'')}</span>${inv.customer_note?'<p>'+esc(inv.customer_note)+'</p>':''}</div></div>`}
function emailStatusKey(inv){return String(inv?.invoice_number||inv?.id||'').trim()}
function localEmailStatuses(){try{const v=JSON.parse(localStorage.getItem(tenantStorageKey('invoice_app_email_status'))||localStorage.getItem(tenantStorageKey('cc_email_status'))||'{}');return v&&typeof v==='object'?v:{}}catch{return {}}}
function getEmailStatus(inv){const direct={sent:!!inv?.email_sent,to:inv?.last_sent_to||'',at:inv?.last_sent_at||''};if(direct.sent||direct.to||direct.at)return direct;const k=emailStatusKey(inv),x=localEmailStatuses()[k]||{};return{sent:!!x.sent,to:x.to||'',at:x.at||''}}
function saveLocalEmailStatus(inv,to,at){const k=emailStatusKey(inv);if(!k)return;const all=localEmailStatuses();all[k]={sent:true,to,at};localStorage.setItem(tenantStorageKey('invoice_app_email_status'),JSON.stringify(all))}
function sentStatusText(inv){const st=getEmailStatus(inv);if(!st.sent)return 'Not sent';let when='';if(st.at){const d=new Date(st.at);if(!Number.isNaN(d.getTime()))when=d.toLocaleString('en-NZ',{day:'numeric',month:'short',year:'numeric',hour:'numeric',minute:'2-digit'})}return `Sent${when?' '+when:''}${st.to?' to '+st.to:''}`}
async function markInvoiceEmailed(inv,to){const at=new Date().toISOString();saveLocalEmailStatus(inv,to,at);const updated={...inv,email_sent:true,last_sent_to:to,last_sent_at:at,updated_at:inv.updated_at||at};cacheInvoice(updated,true);if(sb&&inv?.id&&!String(inv.id).startsWith('local-')){try{const{error}=await sb.from('invoices').update({email_sent:true,last_sent_to:to,last_sent_at:at}).eq('id',inv.id);if(error)console.warn('Email status cloud sync failed; local status retained:',error)}catch(err){console.warn('Email status cloud sync failed; local status retained:',err)}}return updated}
async function sendExistingInvoice(inv,email,btn){const to=String(email||'').trim();if(!to)return toast('Enter an email address to send this invoice');if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(to))return toast('Please check the email address');if(!sb)return toast('Email requires Supabase setup');if(btn){btn.disabled=true;btn.textContent='Sending…'}const pdf=makePdf({...inv,customer_email:to},'blob'),{error}=await sb.functions.invoke('send-invoice',{body:{to,invoice:{...inv,customer_email:to},pdfBase64:pdf.base64,filename:pdf.filename}});if(error){if(btn){btn.disabled=false;btn.textContent=getEmailStatus(inv).sent?'Sent':'Send'}return toast('Email failed: '+error.message)}const updated=await markInvoiceEmailed(inv,to);if(btn){btn.disabled=false;btn.classList.remove('send-unsent');btn.classList.add('send-sent');btn.textContent='Sent';btn.title=sentStatusText(updated)}toast('Invoice emailed successfully to '+to);await renderInvoiceList()}
