function loadForEdit(x){currentId=x.id;sourceQuoteId=x.source_quote_id||null;$('invoiceNumber').value=x.invoice_number;$('invoiceDate').value=x.invoice_date;$('dueDate').value=x.due_date;$('customerName').value=x.customer_name||'';$('customerAddress').value=x.customer_address||'';$('customerEmail').value=x.customer_email||'';$('reference').value=x.reference||'';$('customerNote').value=x.customer_note||'';items=x.items||[];$('discountType').value=x.discount_type||'percent';$('discountValue').value=num(x.discount_value)||'';$('amountPaid').value=num(x.amount_paid)||'';$('recurringEnabled').checked=!!x.recurring;$('recurringFrequency').value=x.recurring_frequency||'fortnightly';$('recurringOptions').style.display=x.recurring?'block':'none';renderItems();recalc();switchView('create');toast('Invoice loaded for editing')}
let lastInvoiceView='create';
window.switchView=function switchView(v){
  const invoiceViews=['create','invoices','settings'];
  const target=$('view-'+v);
  if(!target)return;
  if(invoiceViews.includes(v))lastInvoiceView=v;
  document.querySelectorAll('.view').forEach(x=>x.classList.remove('active'));
  target.classList.add('active');
  document.querySelectorAll('.nav-btn').forEach(x=>x.classList.toggle('active',invoiceViews.includes(v)?x.dataset.module==='invoicing':x.dataset.view===v));
  const invoiceNav=$('invoiceModuleNav');
  if(invoiceNav)invoiceNav.hidden=!invoiceViews.includes(v);
  document.querySelectorAll('[data-invoice-view]').forEach(x=>x.classList.toggle('active',x.dataset.invoiceView===v));
  if(v==='invoices')renderInvoiceList();if(v==='customers')renderCustomers();if(v==='settings')loadSettingsForm();if(v==='reports')initReports();if(v==='jobcosting')window.JobCosting?.onShow?.();if(v==='admin')window.SAAS?.renderAdmin?.()
}
