function renderBankSettings(){$('bankSettings').innerHTML=settings.bankAccounts.map((b,i)=>`<div class="settings-row bank-row"><label>Account label<input data-bank-i="${i}" data-bank-k="name" value="${esc(b.name)}"></label><label>Account number<input data-bank-i="${i}" data-bank-k="account" value="${esc(b.account)}"></label><label class="default-check"><input type="radio" name="defaultBank" data-default-bank="${i}" ${b.isDefault?'checked':''}> Default</label><button class="danger" type="button" data-remove-bank="${i}">Remove</button></div>`).join('');$('bankSettings').querySelectorAll('[data-bank-k]').forEach(x=>x.oninput=e=>{settings.bankAccounts[+e.target.dataset.bankI][e.target.dataset.bankK]=e.target.value;renderSettingsPreview()});$('bankSettings').querySelectorAll('[data-default-bank]').forEach(x=>x.onchange=e=>{settings.bankAccounts.forEach((b,j)=>b.isDefault=j===+e.target.dataset.defaultBank);renderSettingsPreview()});$('bankSettings').querySelectorAll('[data-remove-bank]').forEach(x=>x.onclick=()=>{if(settings.bankAccounts.length===1)return toast('Keep at least one bank account');settings.bankAccounts.splice(+x.dataset.removeBank,1);if(!settings.bankAccounts.some(b=>b.isDefault))settings.bankAccounts[0].isDefault=true;renderBankSettings();renderSettingsPreview()})}
