function setReportRange(kind){const now=new Date(),end=new Date(now.getFullYear(),now.getMonth(),now.getDate());let start;if(kind==='last-month'){start=new Date(now.getFullYear(),now.getMonth()-1,1);const last=new Date(now.getFullYear(),now.getMonth(),0);$('reportFrom').value=isoDate(start);$('reportTo').value=isoDate(last)}else{const months=Number(kind);start=new Date(now.getFullYear(),now.getMonth()-(months-1),1);$('reportFrom').value=isoDate(start);$('reportTo').value=isoDate(end)}runReport()}
async function initReports(){if(!$('reportFrom').value||!$('reportTo').value)setReportRange('6');else runReport()}
async function runReport(){const from=$('reportFrom').value,to=$('reportTo').value;if(!from||!to)return toast('Choose a from and to date');if(from>to)return toast('The from date must be before the to date');const arr=(await allInvoices()).filter(x=>x.invoice_date>=from&&x.invoice_date<=to);currentReportInvoices=arr;let net=0,gst=0,total=0;arr.forEach(x=>{net+=Math.max(0,num(x.total)-num(x.gst));gst+=num(x.gst);total+=num(x.total)});$('reportNet').textContent=money(net);$('reportGst').textContent=money(gst);$('reportTotal').textContent=money(total);$('reportCount').textContent=arr.length;$('reportPeriodLabel').textContent=`${from} to ${to}`;const grouped={};arr.forEach(x=>{const k=monthKey(x.invoice_date),c=invoiceCalcFrom(x);if(!grouped[k])grouped[k]={count:0,net:0,gst:0,fee:0,total:0};grouped[k].count++;grouped[k].net+=Math.max(0,num(x.total)-num(x.gst));grouped[k].gst+=num(x.gst);grouped[k].fee+=c.extraFee;grouped[k].total+=num(x.total)});const months=[];let d=new Date(from+'T12:00:00'),end=new Date(to+'T12:00:00');d=new Date(d.getFullYear(),d.getMonth(),1);while(d<=end){months.push(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`);d.setMonth(d.getMonth()+1)};$('reportRows').innerHTML=months.map(k=>{const x=grouped[k]||{count:0,net:0,gst:0,fee:0,total:0};return`<tr><td><strong>${esc(monthLabel(k))}</strong></td><td>${x.count}</td><td>${money(x.net)}</td><td>${money(x.gst)}</td><td>${money(x.fee)}</td><td><strong>${money(x.total)}</strong></td></tr>`}).join('')||'<tr><td colspan="6">No invoices in this period.</td></tr>';renderSalesChart(months,grouped)}
function renderSalesChart(months,grouped){if(!window.Chart)return;const canvas=$('salesChart'),labels=months.map(monthLabel),values=months.map(k=>(grouped[k]||{}).total||0);if(salesChart)salesChart.destroy();const valueLabels={id:'valueLabels',afterDatasetsDraw(chart){const{ctx}=chart;ctx.save();ctx.font='600 11px system-ui';ctx.textAlign='center';ctx.textBaseline='bottom';ctx.fillStyle='#405462';chart.getDatasetMeta(0).data.forEach((bar,i)=>ctx.fillText(money(values[i]),bar.x,bar.y-5));ctx.restore()}};salesChart=new Chart(canvas,{type:'bar',data:{labels,datasets:[{label:'Total invoiced',data:values,backgroundColor:settings.primaryColor||'#082f4f',borderRadius:7,maxBarThickness:60}]},options:{responsive:true,maintainAspectRatio:false,layout:{padding:{top:28}},plugins:{legend:{display:false},tooltip:{callbacks:{label:c=>money(c.raw)}}},scales:{y:{beginAtZero:true,ticks:{callback:v=>'$'+v.toLocaleString('en-NZ')}}}},plugins:[valueLabels]})}
function exportCsvRows(arr,filename='invoices.csv'){const headers=['invoice_date','invoice_number','customer_name','customer_address','customer_email','subtotal','discount','service_fee_or_tax','gst','total','amount_paid','balance_due','recurring_frequency'];const rows=arr.map(x=>{const c=invoiceCalcFrom(x);return[x.invoice_date,x.invoice_number,x.customer_name,x.customer_address||'',x.customer_email||'',num(x.subtotal),c.discountAmount,c.extraFee,num(x.gst),num(x.total),c.amountPaid,c.balanceDue,x.recurring_frequency||'']});const quote=v=>'"'+String(v??'').replace(/"/g,'""')+'"',csv=[headers.join(','),...rows.map(r=>r.map(quote).join(','))].join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
async function getRules(){if(sb){const{data,error}=await sb.from('recurring_rules').select('*');if(!error)return data||[]}return JSON.parse(localStorage.getItem(tenantStorageKey('invoice_app_recurring_rules'))||localStorage.getItem(tenantStorageKey('cc_recurring_rules'))||'[]')}
async function putRule(rule){if(sb){const{error}=await sb.from('recurring_rules').upsert(rule);if(!error)return true}let a=JSON.parse(localStorage.getItem(tenantStorageKey('invoice_app_recurring_rules'))||localStorage.getItem(tenantStorageKey('cc_recurring_rules'))||'[]'),i=a.findIndex(x=>x.id===rule.id);if(i>=0)a[i]=rule;else a.push(rule);localStorage.setItem(tenantStorageKey('invoice_app_recurring_rules'),JSON.stringify(a));return true}
async function removeRuleForInvoice(invoiceId){const rules=await getRules(),found=rules.filter(r=>String(r.source_invoice_id)===String(invoiceId));for(const r of found){if(sb)await sb.from('recurring_rules').delete().eq('id',r.id);else{let a=JSON.parse(localStorage.getItem(tenantStorageKey('invoice_app_recurring_rules'))||localStorage.getItem(tenantStorageKey('cc_recurring_rules'))||'[]');localStorage.setItem(tenantStorageKey('invoice_app_recurring_rules'),JSON.stringify(a.filter(x=>x.id!==r.id)))}}}
async function syncRecurringRule(inv){if(!inv)return;if(!inv.recurring){await removeRuleForInvoice(inv.id);return}const rules=await getRules(),old=rules.find(r=>String(r.source_invoice_id)===String(inv.id)),template={customer_id:inv.customer_id,customer_name:inv.customer_name,customer_address:inv.customer_address,customer_email:inv.customer_email,reference:inv.reference,customer_note:inv.customer_note,items:inv.items,discount_type:inv.discount_type,discount_value:inv.discount_value,amount_paid:0,company_snapshot:inv.company_snapshot};await putRule({id:old?.id||makeLocalId(),source_invoice_id:String(inv.id),frequency:inv.recurring_frequency||'fortnightly',next_invoice_date:old?.next_invoice_date||addFrequency(inv.invoice_date,inv.recurring_frequency||'fortnightly'),template,active:true,updated_at:new Date().toISOString()})}
async function processRecurringInvoices(){const today=isoDate(),rules=await getRules();let made=0;for(const rule of rules.filter(r=>r.active&&r.next_invoice_date&&r.next_invoice_date<=today)){let next=rule.next_invoice_date,guard=0;while(next<=today&&guard++<24){const tpl=rule.template||{},snap=tpl.company_snapshot||settings,tx=taxConfig(snap),subtotal=(tpl.items||[]).reduce((a,x)=>a+num(x.qty)*num(x.unit_price),0),discountType=tpl.discount_type||'percent',discountValue=num(tpl.discount_value),discountAmount=discountType==='fixed'?Math.min(subtotal,discountValue):subtotal*Math.min(100,discountValue)/100,after=Math.max(0,subtotal-discountAmount),extraFee=tx.extraFeeEnabled?after*tx.extraFeeRate/100:0,gst=(after+extraFee)*tx.gstRate/100,total=after+extraFee+gst,p={invoice_number:await nextInvoiceNo(),invoice_date:next,due_date:addDays(next,snap.dueDays??3),customer_id:tpl.customer_id||null,customer_name:tpl.customer_name||'',customer_address:tpl.customer_address||'',customer_email:tpl.customer_email||'',reference:tpl.reference||'',customer_note:tpl.customer_note||'',items:tpl.items||[],subtotal,discount_type:discountType,discount_value:discountValue,discount_amount:discountAmount,extra_fee:extraFee,gst,total,amount_paid:0,balance_due:total,recurring:false,recurring_frequency:rule.frequency,company_snapshot:snap,updated_at:new Date().toISOString()};const saved=await persistInvoice(p,false);if(saved)made++;next=addFrequency(next,rule.frequency)}rule.next_invoice_date=next;rule.updated_at=new Date().toISOString();await putRule(rule)}if(made)toast(`${made} recurring invoice${made===1?'':'s'} created`)}

document.querySelectorAll('.nav-btn').forEach(b=>b.onclick=()=>{flashButton(b);if(b.dataset.module==='invoicing')switchView(lastInvoiceView||'create');else switchView(b.dataset.view)});document.querySelectorAll('[data-invoice-view]').forEach(b=>b.onclick=()=>{flashButton(b);switchView(b.dataset.invoiceView)});document.querySelectorAll('button').forEach(b=>b.addEventListener('pointerdown',()=>b.classList.add('pressed')));document.addEventListener('pointerup',()=>document.querySelectorAll('button.pressed').forEach(b=>b.classList.remove('pressed')));
$('addItem').onclick=()=>{addItem();flashButton($('addItem'))};$('clearInvoice').onclick=()=>{newInvoice();flashButton($('clearInvoice'))};$('invoiceDate').onchange=()=>{if(!currentId)$('dueDate').value=addDays($('invoiceDate').value,settings.dueDays??3)};['discountType','discountValue','amountPaid'].forEach(id=>$(id).addEventListener('input',recalc));$('recurringEnabled').onchange=()=>{$('recurringOptions').style.display=$('recurringEnabled').checked?'block':'none';recalc()};
$('previewPdf').onclick=()=>{if(validate()){makePdf();flashButton($('previewPdf'))}};$('saveInvoice').onclick=async()=>{const btn=$('saveInvoice');btn.disabled=true;const old=btn.innerHTML;btn.innerHTML='Saving…';try{const r=await save();if(r){await renderInvoiceList();await newInvoice();flashButton(btn);toast('Invoice saved to My Invoices. Ready for the next invoice.')}}catch(err){console.error('Invoice save failed:',err);toast('Invoice could not be saved: '+(err?.message||'Unknown error'))}finally{btn.disabled=false;if(btn.innerHTML==='Saving…')btn.innerHTML=old}};
$('emailInvoice').onclick=async()=>{let requestedEmail=$('customerEmail').value.trim(),inv=await save();if(!inv)return;await renderInvoiceList();if(!requestedEmail){newInvoice();return toast('Invoice saved. No email entered, so no email was sent.')}if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(requestedEmail)){return toast('Invoice saved. Please check the email address before sending.')}if(!sb){newInvoice();return toast('Invoice saved. Email requires Supabase setup.')}const pdf=makePdf({...inv,customer_email:requestedEmail},'blob'),{error}=await sb.functions.invoke('send-invoice',{body:{to:requestedEmail,invoice:{...inv,customer_email:requestedEmail},pdfBase64:pdf.base64,filename:pdf.filename}});if(error)toast('Invoice saved, but email failed: '+error.message);else{await markInvoiceEmailed(inv,requestedEmail);flashButton($('emailInvoice'));toast('Invoice emailed successfully to '+requestedEmail);}newInvoice()};
$('filterMonth').oninput=renderInvoiceList;$('filterSearch').oninput=renderInvoiceList;$('resetFilters').onclick=()=>{$('filterMonth').value='';$('filterSearch').value='';renderInvoiceList();flashButton($('resetFilters'))};$('exportCsv').onclick=async()=>{exportCsvRows(await allInvoices());flashButton($('exportCsv'))};$('closeModal').onclick=()=>$('invoiceModal').classList.remove('open');$('invoiceModal').onclick=e=>{if(e.target===$('invoiceModal'))$('invoiceModal').classList.remove('open')};
