$('saveSettings').onclick=()=>{const draft=settingsDraft();settings={...settings,...draft,supabaseUrl:$('sSupabaseUrl').value,supabaseKey:$('sSupabaseKey').value};localStorage.setItem('invoice_app_settings',JSON.stringify(settings));initSupabase();applyBranding();recalc();$('configNotice').style.display=settings.gstNumber?'none':'block';flashButton($('saveSettings'));toast('Settings saved')};document.querySelectorAll('.report-range').forEach(b=>b.onclick=()=>{setReportRange(b.dataset.range);flashButton(b)});$('runReport').onclick=()=>{runReport();flashButton($('runReport'))};$('reportExportCsv').onclick=()=>{exportCsvRows(currentReportInvoices,`sales-report-${$('reportFrom').value}-to-${$('reportTo').value}.csv`);flashButton($('reportExportCsv'))};

// v11 Customer CRM
const DEFAULT_CUSTOMER_CATEGORIES=['Residential','Commercial'];
function customerNo(existing=[]){const nums=(existing||[]).map(x=>Number(String(x.customer_number||'').replace(/\D/g,''))||0),stored=Number(localStorage.getItem(tenantStorageKey('invoice_app_customer_seq'))||localStorage.getItem(tenantStorageKey('cc_customer_seq'))||0),n=Math.max(stored,...nums,0)+1;localStorage.setItem(tenantStorageKey('invoice_app_customer_seq'),String(n));return 'C'+String(n).padStart(4,'0')}
function normalizeCustomer(c={}){let contacts=Array.isArray(c.contacts)?c.contacts:[];if(!contacts.length&&(c.contact_name||c.email||c.phone||c.mobile)){contacts=[{id:makeLocalId(),name:c.contact_name||c.name||'',designation:c.designation||'',phone:c.phone||'',mobile:c.mobile||'',email:c.email||'',dob:c.dob||'',billing:true}]}if(contacts.length&&!contacts.some(x=>x.billing))contacts[0].billing=true;return{...c,customer_number:c.customer_number||('C'+Date.now().toString().slice(-7)),customer_type:c.customer_type||'individual',category:c.category||'',name:c.name||c.customer_name||'',address:c.address||'',dob:c.dob||'',contacts,custom_fields:Array.isArray(c.custom_fields)?c.custom_fields:[]}}
function billingContact(c){return(c?.contacts||[]).find(x=>x.billing)||(c?.contacts||[])[0]||null}
async function allCustomers(){if(sb){const{data,error}=await sb.from('customers').select('*').order('customer_number',{ascending:true});if(!error)return(data||[]).map(normalizeCustomer);console.warn(error)}return JSON.parse(localStorage.getItem(tenantStorageKey('invoice_app_customers'))||localStorage.getItem(tenantStorageKey('cc_customers'))||'[]').map(normalizeCustomer)}
async function persistCustomer(c,isEdit=false){c=normalizeCustomer(c);c.updated_at=new Date().toISOString();if(sb){const row={...c,dob:c.dob||null,contacts:(c.contacts||[]).map(x=>({...x,dob:x.dob||null}))};if(!isEdit&&!row.id)delete row.id;const q=isEdit&&row.id?await sb.from('customers').update({...row,id:undefined}).eq('id',row.id).select().single():await sb.from('customers').insert(row).select().single();if(!q.error)return normalizeCustomer(q.data);console.warn(q.error);toast('Customer database error: '+q.error.message);return null}let arr=JSON.parse(localStorage.getItem(tenantStorageKey('invoice_app_customers'))||localStorage.getItem(tenantStorageKey('cc_customers'))||'[]');if(isEdit&&c.id){const i=arr.findIndex(x=>String(x.id)===String(c.id));if(i>=0)arr[i]=c;else arr.push(c)}else{c.id=c.id||makeLocalId();c.created_at=c.created_at||new Date().toISOString();arr.push(c)}localStorage.setItem(tenantStorageKey('invoice_app_customers'),JSON.stringify(arr));return c}
async function deleteCustomer(id){if(sb){const{error}=await sb.from('customers').delete().eq('id',id);if(error)return toast(error.message)}else{let a=await allCustomers();localStorage.setItem(tenantStorageKey('invoice_app_customers'),JSON.stringify(a.filter(x=>String(x.id)!==String(id))))}toast('Customer deleted');renderCustomers();refreshCustomerPickers()}
function customerCategories(){let a;try{a=JSON.parse(localStorage.getItem(tenantStorageKey('invoice_app_customer_categories'))||localStorage.getItem(tenantStorageKey('cc_customer_categories'))||'null')}catch{}return Array.isArray(a)&&a.length?a:DEFAULT_CUSTOMER_CATEGORIES.slice()}
function saveCustomerCategories(a){localStorage.setItem(tenantStorageKey('invoice_app_customer_categories'),JSON.stringify([...new Set(a.map(x=>String(x).trim()).filter(Boolean))]));refreshCustomerPickers();renderCategoryManager()}
async function refreshCustomerPickers(){const customers=await allCustomers(),cats=customerCategories();if($('customerNameOptions'))$('customerNameOptions').innerHTML=customers.map(c=>`<option value="${esc(c.name)}">${esc(c.customer_number)}${c.category?' · '+esc(c.category):''}</option>`).join('');if($('customerCategoryOptions'))$('customerCategoryOptions').innerHTML=cats.map(x=>`<option value="${esc(x)}"></option>`).join('');if($('customerCategoryFilter')){const old=$('customerCategoryFilter').value;$('customerCategoryFilter').innerHTML='<option value="">All categories</option>'+cats.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');$('customerCategoryFilter').value=old}}
async function selectCustomerByName(name){const q=String(name||'').trim().toLowerCase();if(!q){selectedCustomerId=null;return}const customers=await allCustomers(),c=customers.find(x=>String(x.name).trim().toLowerCase()===q);if(!c){selectedCustomerId=null;if($('selectedCustomerHint'))$('selectedCustomerHint').textContent='New customer — complete the details and saving the invoice will create the profile.';return}selectedCustomerId=c.id;$('customerName').value=c.name;$('customerAddress').value=c.address||'';$('invoiceCustomerCategory').value=c.category||'';const bc=billingContact(c);$('invoiceBillingContact').value=bc?.name||'';$('customerEmail').value=bc?.email||'';$('invoiceCustomerPhone').value=bc?.phone||'';$('invoiceCustomerMobile').value=bc?.mobile||'';if($('selectedCustomerHint'))$('selectedCustomerHint').textContent=`${c.customer_number}${bc?.name?' · Billing: '+bc.name:''}`}
async function ensureInvoiceCustomer(p){if(p.customer_id){const c=(await allCustomers()).find(x=>String(x.id)===String(p.customer_id));if(c)return c}const byName=(await allCustomers()).find(x=>String(x.name).trim().toLowerCase()===String(p.customer_name).trim().toLowerCase());if(byName){selectedCustomerId=byName.id;return byName}const contact={id:makeLocalId(),name:p.customer_contact_name||p.customer_name,designation:'',phone:p.customer_phone||'',mobile:p.customer_mobile||'',email:p.customer_email||'',dob:'',billing:true};const existing=await allCustomers(),c=await persistCustomer({customer_number:customerNo(existing),customer_type:'individual',category:p.customer_category||'',name:p.customer_name,address:p.customer_address||'',dob:'',contacts:[contact],custom_fields:[]},false);if(c)toast(`New customer ${c.customer_number} created`);return c}
function isBirthday(dob){if(!dob)return false;const s=String(dob).slice(5),t=isoDate().slice(5);return s===t}
function customerBirthdayText(c){const vals=[];if(c.dob)vals.push({label:c.name,dob:c.dob});(c.contacts||[]).forEach(x=>{if(x.dob)vals.push({label:x.name,dob:x.dob})});return vals}
async function renderCustomers(){await refreshCustomerPickers();let arr=await allCustomers(),q=($('customerSearch')?.value||'').toLowerCase(),cat=$('customerCategoryFilter')?.value||'';arr=arr.filter(c=>(!cat||c.category===cat)&&(!q||[c.customer_number,c.name,c.address,c.category,...(c.contacts||[]).flatMap(x=>[x.name,x.email,x.phone,x.mobile])].join(' ').toLowerCase().includes(q)));$('customerRows').innerHTML=arr.map(c=>{const bc=billingContact(c),bds=customerBirthdayText(c),birthday=bds.some(x=>isBirthday(x.dob));return`<tr data-customer-row="${esc(c.id)}"><td><strong>${esc(c.customer_number)}</strong></td><td><strong>${esc(c.name)}</strong><small>${c.customer_type==='business'?'Business':'Individual'}</small></td><td>${esc(c.category||'')}</td><td>${esc(c.address||'')}</td><td>${bc?`${esc(bc.name||'')}<small>${esc(bc.designation||'')}</small>`:''}</td><td>${bc?`${esc(bc.phone||'')}<small>${esc(bc.mobile||'')}</small>`:''}</td><td>${esc(bc?.email||'')}</td><td class="${birthday?'birthday-highlight':''}">${bds.length?bds.map(x=>`${esc(x.label)}: ${esc(x.dob)}${isBirthday(x.dob)?' 🎂':''}`).join('<br>'):''}</td><td><div class="row-actions"><button class="secondary" data-cview="${c.id}">Open</button><button class="secondary" data-cinvoice="${c.id}">Invoice</button><button class="secondary" data-cedit="${c.id}">Edit</button><button class="danger" data-cdel="${c.id}">Delete</button></div></td></tr>`}).join('')||'<tr><td colspan="9">No customers found.</td></tr>';const root=$('customerRows');root.querySelectorAll('[data-cview]').forEach(b=>b.onclick=()=>openCustomerProfile(b.dataset.cview));root.querySelectorAll('[data-cedit]').forEach(b=>b.onclick=()=>openCustomerEditor(b.dataset.cedit));root.querySelectorAll('[data-cinvoice]').forEach(b=>b.onclick=async()=>{const c=(await allCustomers()).find(x=>String(x.id)===String(b.dataset.cinvoice));switchView('create');newInvoice();await selectCustomerByName(c.name)});root.querySelectorAll('[data-cdel]').forEach(b=>b.onclick=()=>{if(confirm('Delete this customer? Existing invoices will remain linked by customer ID.'))deleteCustomer(b.dataset.cdel)})}
function customerFormHtml(c){const cats=customerCategories();return`<div class="form-grid compact customer-core"><label>Customer type<select id="cfType"><option value="individual" ${c.customer_type==='individual'?'selected':''}>Individual</option><option value="business" ${c.customer_type==='business'?'selected':''}>Business</option></select></label><label>Category<input id="cfCategory" list="cfCatList" value="${esc(c.category||'')}" placeholder="Residential / Commercial"><datalist id="cfCatList">${cats.map(x=>`<option value="${esc(x)}"></option>`).join('')}</datalist></label><label class="wide">Customer / Business Name<input id="cfName" value="${esc(c.name||'')}" required></label><label class="wide">Address<textarea id="cfAddress" rows="2">${esc(c.address||'')}</textarea></label><label>Date of Birth (customer)<input id="cfDob" type="date" value="${esc(c.dob||'')}"></label></div><div class="card-title section-space"><h3>Contact people</h3><button type="button" class="secondary" id="cfAddContact">+ Add Contact</button></div><div id="cfContacts"></div><div class="card-title section-space"><h3>Custom information</h3><button type="button" class="secondary" id="cfAddCustom">+ Add Field</button></div><div id="cfCustom"></div>`}
function renderContactDraft(){const r=$('cfContacts');if(!r)return;r.innerHTML=customerContactsDraft.map((x,i)=>`<div class="contact-card"><div class="contact-card-head"><strong>Contact ${i+1}</strong><label class="billing-check"><input type="radio" name="billingContact" data-billing="${i}" ${x.billing?'checked':''}> Billing Contact</label><button class="remove" data-contact-remove="${i}">×</button></div><div class="form-grid compact"><label>Name<input data-ci="${i}" data-ck="name" value="${esc(x.name||'')}"></label><label>Designation / Position<input data-ci="${i}" data-ck="designation" value="${esc(x.designation||'')}"></label><label>Phone<input data-ci="${i}" data-ck="phone" value="${esc(x.phone||'')}"></label><label>Mobile<input data-ci="${i}" data-ck="mobile" value="${esc(x.mobile||'')}"></label><label>Email<input type="email" data-ci="${i}" data-ck="email" value="${esc(x.email||'')}"></label><label>DOB<input type="date" data-ci="${i}" data-ck="dob" value="${esc(x.dob||'')}"></label></div></div>`).join('')||'<p class="hint">No contacts yet.</p>';r.querySelectorAll('[data-ci]').forEach(el=>el.oninput=e=>customerContactsDraft[+e.target.dataset.ci][e.target.dataset.ck]=e.target.value);r.querySelectorAll('[data-billing]').forEach(el=>el.onchange=e=>{customerContactsDraft.forEach((x,j)=>x.billing=j===+e.target.dataset.billing)});r.querySelectorAll('[data-contact-remove]').forEach(b=>b.onclick=()=>{customerContactsDraft.splice(+b.dataset.contactRemove,1);if(customerContactsDraft.length&&!customerContactsDraft.some(x=>x.billing))customerContactsDraft[0].billing=true;renderContactDraft()})}
function renderCustomDraft(){const r=$('cfCustom');if(!r)return;r.innerHTML=customerCustomDraft.map((x,i)=>`<div class="custom-field-row"><input data-fi="${i}" data-fk="label" placeholder="Field name (e.g. Alarm code)" value="${esc(x.label||'')}"><input data-fi="${i}" data-fk="value" placeholder="Value" value="${esc(x.value||'')}"><button class="remove" data-field-remove="${i}">×</button></div>`).join('')||'<p class="hint">Add any extra information you need for this customer.</p>';r.querySelectorAll('[data-fi]').forEach(el=>el.oninput=e=>customerCustomDraft[+e.target.dataset.fi][e.target.dataset.fk]=e.target.value);r.querySelectorAll('[data-field-remove]').forEach(b=>b.onclick=()=>{customerCustomDraft.splice(+b.dataset.fieldRemove,1);renderCustomDraft()})}
async function openCustomerEditor(id=null,prefill=null){editingCustomerId=id;let c=id?(await allCustomers()).find(x=>String(x.id)===String(id)):normalizeCustomer(prefill||{customer_number:customerNo(await allCustomers()),customer_type:'individual',category:'',name:'',address:'',dob:'',contacts:[],custom_fields:[]});if(!c)return;c=normalizeCustomer(c);customerContactsDraft=(c.contacts||[]).map(x=>({...x}));customerCustomDraft=(c.custom_fields||[]).map(x=>({...x}));$('customerModalTitle').textContent=id?'Edit Customer':'Add Customer';$('customerNumberDisplay').textContent=c.customer_number;$('customerFormArea').innerHTML=customerFormHtml(c);renderContactDraft();renderCustomDraft();$('cfAddContact').onclick=()=>{customerContactsDraft.push({id:makeLocalId(),name:'',designation:'',phone:'',mobile:'',email:'',dob:'',billing:customerContactsDraft.length===0});renderContactDraft()};$('cfAddCustom').onclick=()=>{customerCustomDraft.push({label:'',value:''});renderCustomDraft()};$('customerModal').dataset.customerNumber=c.customer_number;$('customerModal').classList.add('open')}
async function saveCustomerEditor(){const name=$('cfName').value.trim();if(!name)return toast('Enter a customer or business name');if(customerContactsDraft.filter(x=>x.billing).length>1)return toast('Select only one billing contact');const c={id:editingCustomerId||undefined,customer_number:$('customerModal').dataset.customerNumber,customer_type:$('cfType').value,category:$('cfCategory').value.trim(),name,address:$('cfAddress').value.trim(),dob:$('cfDob').value,contacts:customerContactsDraft.map(x=>({...x,id:x.id||makeLocalId()})),custom_fields:customerCustomDraft.filter(x=>x.label||x.value)};const out=await persistCustomer(c,!!editingCustomerId);if(!out)return;$('customerModal').classList.remove('open');await refreshCustomerPickers();await renderCustomers();window.dispatchEvent(new CustomEvent('customer:saved',{detail:out}));toast('Customer saved');return out}
async function openCustomerProfile(id){const c=(await allCustomers()).find(x=>String(x.id)===String(id));if(!c)return;const invs=(await allInvoices()).filter(x=>String(x.customer_id||'')===String(c.id));const bc=billingContact(c);$('modalContent').innerHTML=`<div class="customer-profile"><div class="profile-head"><div><h2>${esc(c.name)}</h2><span class="customer-number-pill">${esc(c.customer_number)}</span> <span class="badge">${esc(c.category||c.customer_type)}</span></div><button class="primary" id="profileNewInvoice">Create Invoice</button></div><div class="profile-grid"><div><strong>Address</strong><p>${esc(c.address||'—')}</p></div><div><strong>Customer DOB</strong><p class="${isBirthday(c.dob)?'birthday-highlight':''}">${esc(c.dob||'—')}${isBirthday(c.dob)?' 🎂':''}</p></div></div><h3>Contacts</h3><div class="contacts-profile">${(c.contacts||[]).map(x=>`<div class="contact-card ${x.billing?'billing-contact-card':''}"><strong>${esc(x.name||'Unnamed contact')} ${x.billing?'<span class="badge">Billing</span>':''}</strong><small>${esc(x.designation||'')}</small><p>${esc(x.email||'')}<br>${esc(x.phone||'')} ${esc(x.mobile||'')}</p><p class="${isBirthday(x.dob)?'birthday-highlight':''}">${x.dob?'DOB '+esc(x.dob)+(isBirthday(x.dob)?' 🎂':''):''}</p></div>`).join('')||'<p>No contacts added.</p>'}</div>${c.custom_fields?.length?`<h3>Additional information</h3><div class="custom-profile">${c.custom_fields.map(x=>`<div><strong>${esc(x.label)}</strong><span>${esc(x.value)}</span></div>`).join('')}</div>`:''}<div class="card-title section-space"><h3>Invoice History</h3><span>${invs.length} invoice${invs.length===1?'':'s'}</span></div><div class="customer-invoice-history">${invs.map(x=>`<div class="history-row"><div><strong>${esc(x.invoice_number)}</strong><small>${esc(x.invoice_date)} · ${money(x.total)}</small></div><div class="row-actions"><button class="secondary" data-hview="${x.id}">View</button><button class="secondary" data-hpdf="${x.id}">PDF</button><button class="secondary" data-hedit="${x.id}">Edit</button><button class="secondary" data-hsend="${x.id}">Resend</button></div></div>`).join('')||'<p class="hint">No invoices for this customer yet.</p>'}</div></div>`;$('invoiceModal').classList.add('open');$('profileNewInvoice').onclick=async()=>{switchView('create');$('invoiceModal').classList.remove('open');newInvoice();await selectCustomerByName(c.name)};const getInv=i=>invs.find(x=>String(x.id)===String(i));$('modalContent').querySelectorAll('[data-hview]').forEach(b=>b.onclick=()=>{$('modalContent').innerHTML=previewHtml(getInv(b.dataset.hview))});$('modalContent').querySelectorAll('[data-hpdf]').forEach(b=>b.onclick=()=>makePdf(getInv(b.dataset.hpdf)));$('modalContent').querySelectorAll('[data-hedit]').forEach(b=>b.onclick=()=>{$('invoiceModal').classList.remove('open');loadForEdit(getInv(b.dataset.hedit))});$('modalContent').querySelectorAll('[data-hsend]').forEach(b=>b.onclick=async()=>{const x=getInv(b.dataset.hsend),email=billingContact(c)?.email||x.customer_email;if(!email)return toast('No billing contact email is available');await sendExistingInvoice(x,email,b)})}
function renderCategoryManager(){const a=customerCategories();$('categoryRows').innerHTML=a.map((x,i)=>`<div class="category-row"><input data-cat-index="${i}" value="${esc(x)}"><button class="danger" data-cat-del="${i}">Remove</button></div>`).join('');$('categoryRows').querySelectorAll('[data-cat-index]').forEach(el=>el.onchange=e=>{const a=customerCategories();a[+e.target.dataset.catIndex]=e.target.value;saveCustomerCategories(a)});$('categoryRows').querySelectorAll('[data-cat-del]').forEach(b=>b.onclick=()=>{const a=customerCategories();a.splice(+b.dataset.catDel,1);saveCustomerCategories(a)})}
function downloadCsv(text,name){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
async function exportCustomers(){const arr=await allCustomers(),headers=['customer_number','customer_type','category','customer_name','address','customer_dob','contact_name','designation','phone','mobile','email','contact_dob','billing_contact','custom_fields'];const q=v=>'"'+String(v??'').replace(/"/g,'""')+'"',rows=[];arr.forEach(c=>{const contacts=c.contacts?.length?c.contacts:[{}];contacts.forEach((x,i)=>rows.push([c.customer_number,c.customer_type,c.category,c.name,c.address,c.dob,x.name||'',x.designation||'',x.phone||'',x.mobile||'',x.email||'',x.dob||'',x.billing?'Yes':'No',i===0?JSON.stringify(c.custom_fields||[]):'']))});downloadCsv([headers.join(','),...rows.map(r=>r.map(q).join(','))].join('\n'),'customers.csv');toast('Customer CSV exported')}
function parseCsv(text){const rows=[];let row=[],v='',q=false;for(let i=0;i<text.length;i++){const ch=text[i];if(q){if(ch==='"'&&text[i+1]==='"'){v+='"';i++}else if(ch==='"')q=false;else v+=ch}else if(ch==='"')q=true;else if(ch===','){row.push(v);v=''}else if(ch==='\n'){row.push(v);rows.push(row);row=[];v=''}else if(ch!=='\r')v+=ch}if(v||row.length){row.push(v);rows.push(row)}return rows}
async function importCustomersFile(file){const rows=parseCsv(await file.text());if(rows.length<2)return toast('CSV has no customer rows');const headers=rows[0].map(x=>x.trim().toLowerCase()),ix=n=>headers.indexOf(n),existing=await allCustomers(),group={};for(const r of rows.slice(1)){const name=r[ix('customer_name')]||r[ix('name')]||'';if(!name.trim())continue;const no=r[ix('customer_number')]||'',key=no||name.trim().toLowerCase();if(!group[key])group[key]={customer_number:no||customerNo(existing),customer_type:r[ix('customer_type')]||'individual',category:r[ix('category')]||'',name,address:r[ix('address')]||'',dob:r[ix('customer_dob')]||'',contacts:[],custom_fields:[]};const email=r[ix('email')]||'',cn=r[ix('contact_name')]||'';if(cn||email||r[ix('phone')]||r[ix('mobile')])group[key].contacts.push({id:makeLocalId(),name:cn,designation:r[ix('designation')]||'',phone:r[ix('phone')]||'',mobile:r[ix('mobile')]||'',email,dob:r[ix('contact_dob')]||'',billing:/^(yes|true|1)$/i.test(r[ix('billing_contact')]||'')});const custom=r[ix('custom_fields')];if(custom){try{group[key].custom_fields=JSON.parse(custom)}catch{}}}let count=0;for(const c of Object.values(group)){const old=existing.find(x=>(c.customer_number&&x.customer_number===c.customer_number)||x.name.toLowerCase()===c.name.toLowerCase());if(old){c.id=old.id;if(!c.contacts.length)c.contacts=old.contacts;await persistCustomer(c,true)}else await persistCustomer(c,false);count++}await renderCustomers();toast(`${count} customer record${count===1?'':'s'} imported/updated`)}
// Extend edit-invoice customer restoration without changing legacy invoice behavior.
const _loadForEditV10=loadForEdit;loadForEdit=function(inv){_loadForEditV10(inv);selectedCustomerId=inv.customer_id||null;if($('invoiceCustomerCategory'))$('invoiceCustomerCategory').value=inv.customer_category||'';if($('invoiceBillingContact'))$('invoiceBillingContact').value=inv.customer_contact_name||'';if($('invoiceCustomerPhone'))$('invoiceCustomerPhone').value=inv.customer_phone||'';if($('invoiceCustomerMobile'))$('invoiceCustomerMobile').value=inv.customer_mobile||'';if(inv.customer_id)allCustomers().then(a=>{const c=a.find(x=>String(x.id)===String(inv.customer_id));if(c&&$('selectedCustomerHint'))$('selectedCustomerHint').textContent=`${c.customer_number} · Linked customer`})}
// Invoice emails prefer the currently selected customer's billing contact.
async function preferredInvoiceEmail(fallback){if(selectedCustomerId){const c=(await allCustomers()).find(x=>String(x.id)===String(selectedCustomerId));return billingContact(c)?.email||fallback}return fallback}
