$('addCustomerBtn').onclick=()=>openCustomerEditor();$('closeCustomerModal').onclick=$('cancelCustomer').onclick=()=>$('customerModal').classList.remove('open');$('saveCustomer').onclick=saveCustomerEditor;$('customerModal').onclick=e=>{if(e.target===$('customerModal'))$('customerModal').classList.remove('open')};$('customerSearch').oninput=renderCustomers;$('customerCategoryFilter').onchange=renderCustomers;$('exportCustomersCsv').onclick=exportCustomers;$('importCustomersBtn').onclick=()=>$('importCustomersFile').click();$('importCustomersFile').onchange=e=>{if(e.target.files[0])importCustomersFile(e.target.files[0]);e.target.value=''};$('manageCategoriesBtn').onclick=()=>{renderCategoryManager();$('categoryModal').classList.add('open')};$('closeCategoryModal').onclick=()=>$('categoryModal').classList.remove('open');$('addCategorySave').onclick=()=>{const v=$('newCategoryName').value.trim();if(!v)return;saveCustomerCategories([...customerCategories(),v]);$('newCategoryName').value=''};
